import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.Parameter;
import io.swagger.v3.oas.annotations.Parameters;
import io.swagger.v3.oas.annotations.enums.ParameterIn;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.tags.Tag;

import org.springframework.http.MediaType;

@Tag(name = "ECGI", description = "ECGI 관리 API")
@Controller
@RequestMapping("/web/admin/ecgis")
public class ECGIController extends CommonController {

	@Autowired
	private ECGIService service;

	@Operation(summary = "ECGI 목록 화면", description = "ECGI 목록 화면을 조회합니다.")
	@RequestMapping(value = "", method = RequestMethod.GET)
	public String ecgiListView(@RequestParamMap ParamMap param, Model model) {
		if (CommonUtil.isVulnerability(new String[] {"listLength"}, param)) {
			param.remove("listLength");
		}
		model.addAllAttributes(param);
		return "admin/ecgi/ecgiList";
	}

	@Operation(summary = "ECGI 목록 조회", description = "페이징 처리된 ECGI 목록을 조회합니다.")
	@Parameters({
		@Parameter(name = "start", description = "페이징 시작 위치", example = "0", required = false, schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "length", description = "페이지당 표시 개수", example = "10", required = false, schema = @Schema(type = "integer", format = "int32"))
	})
	@RequestMapping(value = "/ajax", method = RequestMethod.GET)
	public String ecgiList(@RequestParamMap ParamMap param, Model model) throws Exception {
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.getEcgiList(param));
		return JSON_VIEW;
	}

	@Operation(summary = "ECGI 엑셀 등록 화면", description = "ECGI 엑셀 업로드 화면을 조회합니다.")
	@RequestMapping(value = "/excel/new", method = RequestMethod.GET)
	public String createBeaconExcelView(@RequestParamMap ParamMap param, Model model) {
		if (CommonUtil.isVulnerability(new String[] {"listLength"}, param)) {
			param.remove("listLength");
		}
		model.addAllAttributes(param);
		return "admin/ecgi/ecgiExcel";
	}

	@Operation(summary = "ECGI 엑셀 업로드", description = "엑셀 파일을 업로드하여 ECGI를 일괄 등록합니다.")
	@RequestMapping(value = "/excel", method = RequestMethod.POST, consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
	public String createEcgiExcelUpload(@RequestParamMap ParamMap param, Model model
			, @Parameter(description = "ECGI 엑셀 파일") @RequestParam("ecgiExcelFile") MultipartFile ecgiExcelFile) throws LogicException {
		if (!CommonUtil.excelFileExtCheck(CommonUtil.getFileExt(ecgiExcelFile.getOriginalFilename()))){
			throw new LogicException("VALIDATION_FAIL","003");
		}
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		param.put("accountSeq", param.getSessionAttribute("loginAccountSeq"));
		model.addAllAttributes(service.createEcgiExcelUpload(param, ecgiExcelFile));
		return JSON_VIEW;
	}

	@Operation(summary = "샘플 파일 다운로드", description = "ECGI 엑셀 업로드용 샘플 파일을 다운로드합니다.")
	@RequestMapping(value = "/sample", method = RequestMethod.GET)
	public String downloadEcgiExcelSample(@RequestParamMap ParamMap param, Model model) {
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.downloadEcgiExcelSample(param));
		return DOWN_VIEW;
	}

	@Operation(summary = "ECGI 등록 화면", description = "ECGI 등록 화면을 조회합니다.")
	@RequestMapping(value = "/new", method = RequestMethod.GET)
	public String createEcgiView(@RequestParamMap ParamMap param, Model model) {
		if (CommonUtil.isVulnerability(new String[] {"listLength"}, param)) {
			param.remove("listLength");
		}
		model.addAllAttributes(param);
		return "admin/ecgi/ecgi";
	}

	@Operation(summary = "ECGI 등록", description = "새로운 ECGI 정보를 등록합니다.")
	@Parameters({
		@Parameter(name = "location", description = "지역명", example = "서울", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "name", description = "ECGI명", example = "ECGI_01", required = true, schema = @Schema(type = "string")),
