1	package com.ahope.ds.common.aws.kms;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.util.ArrayList;
5	import java.util.Base64;
6	import java.util.Collections;
7	import java.util.List;
8	import java.util.Map;
9	import java.util.concurrent.TimeUnit;
10	
11	import org.slf4j.Logger;
12	import org.slf4j.LoggerFactory;
13	
14	import com.amazonaws.encryptionsdk.AwsCrypto;
15	import com.amazonaws.encryptionsdk.CommitmentPolicy;
16	import com.amazonaws.encryptionsdk.CryptoResult;
17	import com.amazonaws.encryptionsdk.MasterKeyProvider;
18	import com.amazonaws.encryptionsdk.caching.CachingCryptoMaterialsManager;
19	import com.amazonaws.encryptionsdk.caching.CryptoMaterialsCache;
20	import com.amazonaws.encryptionsdk.caching.LocalCryptoMaterialsCache;
21	import com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKey;
22	import com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKeyProvider;
23	import software.amazon.awssdk.auth.credentials.AwsBasicCredentials;
24	import software.amazon.awssdk.auth.credentials.StaticCredentialsProvider;
25	import software.amazon.awssdk.regions.Region;
26	import software.amazon.awssdk.services.kms.KmsClient;
27	
28	import java.net.URI;
29	
30	/**
31	 * AWS Encryption SDK를 사용한 데이터 암복호화 서비스.
32	 * <p>
33	 * AWS Encryption SDK의 Envelope Encryption + Data Key Caching을 활용하여
34	 * KMS API 호출을 최소화하면서 안전한 암복호화를 수행한다.
35	 * <p>
36	 * {@link AwsKmsConfig}에서 CMK별 Bean으로 등록된다:
37	 * <ul>
38	 *   <li>"locationEncryptionService" — CMK 1: 위치/트래픽 (ECGI, GPS)</li>
39	 *   <li>"dataEncryptionService" — CMK 2: 개인정보 (CTN, IMEI 등)</li>
40	 * </ul>
41	 * <p>
42	 * SDK가 내부적으로 처리하는 항목:
43	 * <ul>
44	 *   <li>Data Key 생성 (GenerateDataKey)</li>
45	 *   <li>AES-GCM 암호화/복호화</li>
46	 *   <li>IV 생성 및 관리</li>
47	 *   <li>Envelope 바이너리 포맷 (encrypted message)</li>
48	 *   <li>Encryption Context 바인딩</li>
49	 * </ul>
50	 */
51	public class AwsKmsEncryptionService {
52	
53	    private static final Logger logger = LoggerFactory.getLogger(AwsKmsEncryptionService.class);
54	
55	    /** Data Key 캐시 최대 항목 수 */
56	    private static final int CACHE_CAPACITY = 100;
57	    /** 캐시된 Data Key 최대 유효 시간 (분) */
58	    private static final int MAX_AGE_MINUTES = 5;
59	    /** 하나의 캐시된 Data Key로 암호화할 수 있는 최대 메시지 수 */
60	    private static final int MAX_MESSAGES_PER_KEY = 1000000;
61	
62	    private final AwsCrypto crypto;
63	    private final CachingCryptoMaterialsManager cachingCmm;
64	    private final MasterKeyProvider<KmsMasterKey> masterKeyProvider;
65	
66	    public AwsKmsEncryptionService(String keyArn, String region) {
67	        // 1. AwsCrypto 인스턴스 (RequireEncryptRequireDecrypt = 기본 커밋 정책)
68	        this.crypto = AwsCrypto.builder()
69	                .withCommitmentPolicy(CommitmentPolicy.RequireEncryptRequireDecrypt)
70	                .build();
71	
72	        // 2. KMS Master Key Provider (AWS SDK v2 기반)
73	        //    LocalStack 사용 시 endpoint override + dummy credential 설정
74	        KmsMasterKeyProvider.Builder providerBuilder = KmsMasterKeyProvider.builder()
75	                .defaultRegion(Region.of(region));
76	
77	        String localstackEndpoint = System.getProperty("LOCALSTACK_ENDPOINT");
78	        KmsClient kmsClient;
79	        if (localstackEndpoint != null && !localstackEndpoint.isBlank()) {
80	            logger.info("AwsKmsEncryptionService: Using LocalStack endpoint = {}", localstackEndpoint);
81	            kmsClient = KmsClient.builder()
82	                    .region(Region.of(region))
83	                    .endpointOverride(URI.create(localstackEndpoint))
84	                    .credentialsProvider(StaticCredentialsProvider.create(
85	                            AwsBasicCredentials.create("test", "test")))
86	                    .build();
87	            providerBuilder.customRegionalClientSupplier(r -> kmsClient);
88	        } else {
89	            kmsClient = KmsClient.builder()
90	                    .region(Region.of(region))
91	                    .build();
92	        }
93	
94	        // alias → ARN 변환 (환경 무관)
95	        // AWS Encryption SDK는 암호화 시 헤더에 항상 ARN을 기록하므로
