32	@Aspect
33	@Component
34	public class HistoryAspect {
35		protected Logger logger = LoggerFactory.getLogger(this.getClass());
36	    
37	    @Autowired
38	    private HistoryDAO historyDAO;
39	
40	    @Around("@annotation(history)")
41	    public Object aroundHistory(ProceedingJoinPoint pjp, History history) throws Throwable {
42	        try {
43	            HistoryContext.enable();
44	            return pjp.proceed();
45	        } finally {
46	            HistoryContext.disable();
47	        }
48	    }
49	    
50		@AfterReturning(pointcut = "@annotation(com.ahope.ds.common.extension.annotation.History)", returning = "retVal")
51		public void appendHistoryOnCases(JoinPoint pjp) throws Throwable {
52			logger.info("[ST][HistoryAspect]");
53			
54			HttpServletRequest req = ((ServletRequestAttributes) RequestContextHolder.currentRequestAttributes()).getRequest(); 
55			HttpSession session = req.getSession(false);
56			Object[] args = pjp.getArgs(); // 응답 값
57			
58			ModelMap model = new ModelMap(); // 모델 
59			for (Object arg : args) {
60	            if (arg instanceof ModelMap) model.addAllAttributes((ModelMap) arg);
61	        }
62			if (model.get("err") == null || !"000".equals(model.get("err"))) {
63				logger.info("an exception is thrown");
64			} else if (CommonUtil.isNull(session)) { // 현재 저장된 계정 정보
65				logger.info("session is null");
66			} else {
67		        MethodSignature sig = (MethodSignature) pjp.getSignature();
68		        Method method = sig.getMethod();
69		        if (method.getDeclaringClass().isInterface()) method = pjp.getTarget().getClass().getMethod(sig.getName(), sig.getParameterTypes());
70		        
71		        // 입력받은 값 확인 
72		        History history = method.getAnnotation(History.class);
73		        HistoryType[] historyTypeList = history.historyType();
74		        String reqType = history.reqType();
75		        boolean checkCorporation = history.checkCorporation();
76		        
77		        for (HistoryType historyType : historyTypeList) {
78		        	ParamMap param = new ParamMap();
79		        	switch(historyType) {
80			        	case LOGIN: // 로그인 
81			        		logger.info("History Type - LOGIN");
82			        		String id = req.getParameter("id");
83			        		String accountSeq = model.get("accountSeq") != null ? 
84			        				String.valueOf(model.get("accountSeq")) : String.valueOf(session.getAttribute("loginAccountSeq"));
85			        		param.put("id", id);
86		        			param.put("accountSeq", accountSeq);
87		        			param.put("ip", req.getRemoteAddr());
88		        			param.put("reqType", reqType);
89	
90			        		historyDAO.insertPersonalInfoHistory(param);
91			        		break;
92			        		
93			        	case PERSONAL_INFO_ACCESS: // 개인정보 조회
94			        		logger.info("History Type - PERSONAL_INFO_ACCESS");
95			        		if(checkCorporation) { 
96			        			Object corpYn =  ((Map<String, Object>)  model.get("member")).get("corporationYn");
97			        			boolean isCorporate = "1".equals(String.valueOf(corpYn));
98			        			if (isCorporate) {
99			        				logger.info("isCorporate: {}", isCorporate);
100			        				break; // 기업 회원이라면 break;
101			        			}
102			        		}
103			        		String dbQuery = MybatisExecuteInterceptor.getAccessExecutedSqls();
104			        		if (CommonUtil.isNull(dbQuery)) {
105			        			logger.info("query is null");
106			        			break;
107			        		}
108			        		param.put("id", session.getAttribute("loginId"));
109			        		param.put("accountSeq", session.getAttribute("loginAccountSeq"));
110			        		param.put("ip", req.getRemoteAddr());
111			        		param.put("reqType", reqType);
112			        		param.put("dbQuery", dbQuery);
113	
114			        		historyDAO.insertPersonalInfoHistory(param);
115			        		break;
116			        		
117			        	case EXCEL_DOWNLOAD: // 엑셀 다운로드
118			        		logger.info("History Type - EXCEL_DOWNLOAD");
119			        		String excelType = req.getParameter("excelType");
120			        		
121			        		if (!CommonUtil.isNull(excelType) && excelType.equals("all")) break; // 전체조회라면 break
122			        		
123			        		param.put("id", session.getAttribute("loginId"));
124			        		param.put("accountSeq", session.getAttribute("loginAccountSeq"));
125			        		param.put("ip", req.getRemoteAddr());
126			        		param.put("reqType", reqType);
127			        		param.put("reason", req.getParameter("excelReason"));
128	
129			        		historyDAO.insertExcelDownloadHistory(param);
130			        		break;
131			        		
132			        	case PERMISSION: // 권한 관리
133			        		logger.info("History Type - PERMISSION");
134			        		ParamMap paramMap = null; // param 
135			        		for (Object arg : args) {
136			                    if (arg instanceof ParamMap) {
137			                    	paramMap = (ParamMap) arg;
138			                    	break;
139			                    }
140			                }
141			        		String permissionReason = (String) paramMap.getString("reason");
142			        		String accountType = (String) paramMap.getString("authz");
143			        		String targetId = (String) paramMap.getString("id");
144			        		
145			        		if (!CommonUtil.isNull(permissionReason)) {
146			        			param.put("id", session.getAttribute("loginId"));
147			        			param.put("accountSeq", session.getAttribute("loginAccountSeq"));
148			        			param.put("ip", req.getRemoteAddr());
149			        			param.put("reqType", reqType);
150			        			param.put("accountType", accountType);
151			        			param.put("reason", permissionReason);
152			        			param.put("targetAccountSeq",  model.get("accountSeq").toString());
153			        			param.put("targetId", targetId);
154	
155			        			historyDAO.insertPermissionHistory(param);
156			        			logger.info("insertPermissionHistory");
