import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

/**
 * Black-Box API Integration Test
 *
 * @target-controller CryptoController (src/main/java/com/ahope/ds/web/superadmin/crypto/controller/CryptoController.java)
 * @target-api POST /web/super/admin/crypto/personal
 *
 * 인증: SuperAdminLoginInterceptor (세션 기반, AUTHZ='07'=SYSTEM 이면 전 경로 허용).
 * 외부 HTTP 연동 없음 — 복호화는 AWS KMS(dataEncryptionService, CMK-2 / LocalStack) 사용. WireMock 불필요.
 * 응답: HTTP 200 고정, JSON { err, cryptoResult }. err "000"=성공, "115"=잘못된 암호문, "001"=필수값 누락.
 *
 * 도메인 데이터가 없어 슈퍼관리자 세션은 클래스 단위로 1회 획득한다(@BeforeAll는 인증 픽스처만 처리).
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
@Execution(ExecutionMode.CONCURRENT)
class SuperAdminCryptoPersonalBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:13306/smart_plant");
    private static final String DB_USER = System.getProperty("test.db.user", "smartplant");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "smartplant1234");

    private static final String ADMIN_ID = "sysadmincrypto";
    private static final String ADMIN_PW = "testpw";

    private static String sessionId;

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    @BeforeAll
    void beforeAll() throws Exception {
        RestAssured.baseURI = BASE_URL;
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/super-admin-crypto-personal-teardown.sql", getClass());
            TestUtil.executeSql(conn, "sql/super-admin-crypto-personal-setup.sql", getClass());
            sessionId = TestUtil.adminLogin(BASE_URL, ADMIN_ID, ADMIN_PW, conn);
        }
    }

    @AfterAll
    void afterAll() throws Exception {
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/super-admin-crypto-personal-teardown.sql", getClass());
        }
    }

    private io.restassured.specification.RequestSpecification authed() {
        return given().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded");
    }

    // ---------------------------------------------------------------- NTC

    @Test
    void NTC_getPersonalDecryption_ctn() {
        String plain = "01099887766";
        String cipher = TestUtil.kmsEncrypt(plain); // CMK-2 encrypt
        authed().formParam("cryptoContent", cipher)
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo(plain));
    }

    @Test
    void NTC_getPersonalDecryption_imei() {
        String plain = "356938035643809";
        String cipher = TestUtil.kmsEncrypt(plain);
        authed().formParam("cryptoContent", cipher)
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo(plain));
    }

    @Test
    void NTC_getPersonalDecryption_koreanName() {
        String plain = "홍길동";
        String cipher = TestUtil.kmsEncrypt(plain);
        authed().formParam("cryptoContent", cipher)
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo(plain));
    }

    // ---------------------------------------------------------------- VTC

    @Test
    void VTC_cryptoContent_NULL() {
        // cryptoContent 파라미터 누락 → RequestParamMapArgumentResolver 가 "001" 반환
        authed()
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("001"));
    }

    @Test
    void VTC_cryptoContent_EMPTY() {
        // 빈 문자열은 CommonUtil.isNull("")==true → 필수값 누락 "001"
        authed().formParam("cryptoContent", "")
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("001"));
    }

    // ---------------------------------------------------------------- ATC

    @Test
    void ATC_cryptoContent_invalidCiphertext() {
        // 유효한 Base64지만 KMS 암호문이 아님 → decrypt RuntimeException → "115"
        authed().formParam("cryptoContent", "bm90LWEtcmVhbC1jaXBoZXJ0ZXh0")
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("115"));
    }

    @Test
    void ATC_cryptoContent_nonBase64() {
        // Base64 디코딩 자체가 실패 → RuntimeException → "115"
        authed().formParam("cryptoContent", "!!not-base64!!")
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("115"));
    }
}

