package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.nullValue;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.HashMap;
import java.util.Map;

import io.restassured.RestAssured;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

/**
 * Black-Box API Integration Test
 *
 * @target-controller MemberController (src/main/java/com/ahope/ds/web/admin/member/controller/MemberController.java)
 * @target-api GET /web/admin/members/qos/{memberSeq}
 *
 * 인증: AdminLoginInterceptor (세션, AUTHZ='02'=NORMAL). GET /members/qos 는 추가 권한 제약 없음.
 * 서비스: MemberService.getMemberQosStatus → MEMBER_QOS_STATUS 조회.
 * 응답: HTTP 200, JSON { err:"000", memberQosStatus: { qosStatus } } (행이 없으면 memberQosStatus=null).
 * 외부 HTTP 연동 없음 → WireMock 불필요.
 *
 * 병렬 격리: 인증 픽스처는 클래스 단위(@BeforeAll)로 1회 세팅, QOS 데이터는 메서드별 고유 MEMBER_SEQ.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
@Execution(ExecutionMode.CONCURRENT)
class AdminMembersQosBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:13306/smart_plant");
    private static final String DB_USER = System.getProperty("test.db.user", "smartplant");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "smartplant1234");

    private static final String ADMIN_ID = "qosadmin";
    private static final String ADMIN_PW = "testpw";
    private static String sessionId;

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    /** 메서드명 기반 결정적 고유 MEMBER_SEQ (병렬 격리 키, 90x xxx xxx 대역). */
    private static long uniqueSeq(TestInfo info) {
        return 900_000_000L + Math.floorMod(info.getTestMethod().get().getName().hashCode(), 90_000_000L);
    }

    @BeforeAll
    void beforeAll() throws Exception {
        RestAssured.baseURI = BASE_URL;
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/admin-members-qos-teardown.sql", getClass());
            TestUtil.executeSql(conn, "sql/admin-members-qos-setup.sql", getClass());
            sessionId = TestUtil.adminLogin(BASE_URL, ADMIN_ID, ADMIN_PW, conn);
        }
    }

    @AfterAll
    void afterAll() throws Exception {
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/admin-members-qos-teardown.sql", getClass());
        }
    }

    private void runQosCase(TestInfo info, String qosStatus) throws Exception {
        long seq = uniqueSeq(info);
        Map<String, String> p = new HashMap<>();
        p.put("SEQ", String.valueOf(seq));
        p.put("QOS", qosStatus);
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSqlTemplate(conn, "sql/admin-members-qos-data-teardown.sql", p, getClass());
            TestUtil.executeSqlTemplate(conn, "sql/admin-members-qos-data-setup.sql", p, getClass());
        }
        try {
            given().baseUri(BASE_URL)
                .cookie("SESSION", sessionId)
                .header("X-Requested-With", "XMLHttpRequest")
            .when()
                .get("/web/admin/members/qos/" + seq)
            .then().statusCode(200)
                .body("err", equalTo("000"))
                .body("memberQosStatus.qosStatus", equalTo(qosStatus));
        } finally {
            try (Connection conn = getDbConnection()) {
                TestUtil.executeSqlTemplate(conn, "sql/admin-members-qos-data-teardown.sql", p, getClass());
            }
        }
    }

    // ---------------------------------------------------------------- NTC

    @Test
    void NTC_getMemberQosStatus_normal(TestInfo info) throws Exception {
        runQosCase(info, "01"); // 정상
    }

    @Test
    void NTC_getMemberQosStatus_controlled(TestInfo info) throws Exception {
        runQosCase(info, "02"); // 제어 상태
    }

    @Test
    void NTC_getMemberQosStatus_released(TestInfo info) throws Exception {
        runQosCase(info, "03"); // 해제 상태
    }

    // ---------------------------------------------------------------- ATC

    @Test
    void ATC_getMemberQosStatus_notFound(TestInfo info) throws Exception {
        // QOS 행이 없는 memberSeq → memberQosStatus == null, err="000"
        long seq = uniqueSeq(info);
        Map<String, String> p = new HashMap<>();
        p.put("SEQ", String.valueOf(seq));
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSqlTemplate(conn, "sql/admin-members-qos-data-teardown.sql", p, getClass());
        }
        given().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when()
            .get("/web/admin/members/qos/" + seq)
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("memberQosStatus", nullValue());
    }

    @Test
    void ATC_getMemberQosStatus_noSession() {
        // 세션 없이 ajax GET → AdminLoginInterceptor 가 401 반환
        given().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when()
            .get("/web/admin/members/qos/900000001")
        .then().statusCode(401);
    }
}

