package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.HashMap;
import java.util.Map;

import io.restassured.RestAssured;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

/**
 * Black-Box API Integration Test
 *
 * @target-controller ECGIController (src/main/java/com/ahope/ds/web/admin/ecgi/controller/ECGIController.java)
 * @target-api GET /web/admin/ecgis/ajax
 *
 * 인증: AdminLoginInterceptor (세션, AUTHZ='02'). /ecgis/ajax 는 추가 권한 제약 없음.
 * 서비스: ECGIService.getEcgiList → ECGI (CLIENT_SEQ=loginClientSeq) 조회 후 ECGI 컬럼을 CMK-1로 복호화.
 * 응답: HTTP 200, JSON { err:"000", iTotalRecords, iTotalDisplayRecords, aaData:[{ecgiSeq,name,clientSeq,location,ecgi,regTime}] }.
 * 외부 HTTP 연동 없음 (복호화는 KMS/LocalStack) → WireMock 불필요.
 *
 * 병렬 격리: 목록은 클래스 공용 clientSeq(97501) 로 스코프되므로, 공유되는 iTotalRecords/size 대신
 * 메서드별 고유 ecgiSeq 로 aaData.find 하여 그 행의 복호화 값을 정확히 검증한다.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
@Execution(ExecutionMode.CONCURRENT)
class AdminEcgisAjaxBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:13306/smart_plant");
    private static final String DB_USER = System.getProperty("test.db.user", "smartplant");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "smartplant1234");

    private static final String ADMIN_ID = "ecgiadmin";
    private static final String ADMIN_PW = "testpw";
    private static String sessionId;

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private static long uniqueSeq(TestInfo info) {
        return 900_000_000L + Math.floorMod(info.getTestMethod().get().getName().hashCode(), 90_000_000L);
    }

    @BeforeAll
    void beforeAll() throws Exception {
        RestAssured.baseURI = BASE_URL;
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/admin-ecgis-ajax-teardown.sql", getClass());
            TestUtil.executeSql(conn, "sql/admin-ecgis-ajax-setup.sql", getClass());
            sessionId = TestUtil.adminLogin(BASE_URL, ADMIN_ID, ADMIN_PW, conn);
        }
    }

    @AfterAll
    void afterAll() throws Exception {
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/admin-ecgis-ajax-teardown.sql", getClass());
        }
    }

    private void runEcgiCase(TestInfo info, String name, String location, String plainEcgi) throws Exception {
        long seq = uniqueSeq(info);
        Map<String, String> p = new HashMap<>();
        p.put("SEQ", String.valueOf(seq));
        p.put("NAME", name);
        p.put("LOCATION", location);
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSqlTemplate(conn, "sql/admin-ecgis-ajax-data-teardown.sql", p, getClass());
            TestUtil.executeSqlTemplate(conn, "sql/admin-ecgis-ajax-data-setup.sql", p, getClass());
            TestUtil.encryptEcgi(conn, seq, plainEcgi); // ECGI 컬럼을 CMK-1 암호문으로 치환
        }
        try {
            given().baseUri(BASE_URL)
                .cookie("SESSION", sessionId)
                .header("X-Requested-With", "XMLHttpRequest")
            .when()
                .get("/web/admin/ecgis/ajax")
            .then().statusCode(200)
                .body("err", equalTo("000"))
                .body("aaData.find { it.ecgiSeq == " + seq + " }.name", equalTo(name))
                .body("aaData.find { it.ecgiSeq == " + seq + " }.location", equalTo(location))
                .body("aaData.find { it.ecgiSeq == " + seq + " }.ecgi", equalTo(plainEcgi))
                .body("aaData.find { it.ecgiSeq == " + seq + " }.clientSeq", equalTo(97501));
        } finally {
            try (Connection conn = getDbConnection()) {
                TestUtil.executeSqlTemplate(conn, "sql/admin-ecgis-ajax-data-teardown.sql", p, getClass());
            }
        }
    }

    // ---------------------------------------------------------------- NTC

    @Test
    void NTC_ecgiList_seoul(TestInfo info) throws Exception {
        runEcgiCase(info, "ECGI_SEOUL", "서울", "1234501111");
    }

    @Test
    void NTC_ecgiList_busan(TestInfo info) throws Exception {
        runEcgiCase(info, "ECGI_BUSAN", "부산", "9876502222");
    }

    @Test
    void NTC_ecgiList_daejeon(TestInfo info) throws Exception {
        runEcgiCase(info, "ECGI_DAEJEON", "대전", "5555503333");
    }

    // ---------------------------------------------------------------- ATC

    @Test
    void ATC_ecgiList_noSession() {
        // 세션 없이 /ajax 요청 → URI에 "/ajax" 포함이므로 AdminLoginInterceptor 가 401
        given().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when()
            .get("/web/admin/ecgis/ajax")
        .then().statusCode(401);
    }
}

