import java.sql.Connection;
import java.sql.DriverManager;

import io.restassured.RestAssured;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

/**
 * Black-Box API Integration Test
 *
 * @target-controller TrafficController (src/main/java/com/ahope/ds/web/admin/traffic/controller/TrafficController.java)
 * @target-api POST /web/admin/traffic/excel/make
 *
 * 인증: AdminLoginInterceptor. 블랙리스트에 의해 이 경로는 AUTHZ='07'(SYSTEM) 만 허용.
 * 서비스: TrafficService.makeTrafficExcel — 동기 구간은 목록 조회 후 즉시 반환, 엑셀 생성은 별도 스레드(비동기).
 * 응답: HTTP 200, JSON { err:"000" } (엑셀 생성 결과는 비동기 → 응답 본문에 없음).
 * excelReason 취약값(XSS) → LogicException("VULNERABLE_VALUE","002").
 * 외부 HTTP 연동 없음 (엑셀 템플릿/업로드는 S3=LocalStack) → WireMock 불필요.
 *
 * 응답이 err 뿐이므로 도메인 데이터가 필요 없다(빈 목록이어도 err="000"). 세션은 클래스 단위 1회 획득.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
@Execution(ExecutionMode.CONCURRENT)
class AdminTrafficExcelMakeBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:13306/smart_plant");
    private static final String DB_USER = System.getProperty("test.db.user", "smartplant");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "smartplant1234");

    private static final String ADMIN_ID = "systraffic";
    private static final String ADMIN_PW = "testpw";
    private static String sessionId;

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    @BeforeAll
    void beforeAll() throws Exception {
        RestAssured.baseURI = BASE_URL;
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/admin-traffic-excel-make-teardown.sql", getClass());
            TestUtil.executeSql(conn, "sql/admin-traffic-excel-make-setup.sql", getClass());
            sessionId = TestUtil.adminLogin(BASE_URL, ADMIN_ID, ADMIN_PW, conn);
        }
    }

    @AfterAll
    void afterAll() throws Exception {
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/admin-traffic-excel-make-teardown.sql", getClass());
        }
    }

    private io.restassured.specification.RequestSpecification authed() {
        return given().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded");
    }

    // ---------------------------------------------------------------- NTC

    @Test
    void NTC_makeTrafficExcel_calculateMonthly() {
        authed()
            .formParam("searchType", "CTN")
            .formParam("searchValue", "")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("searchDataType", "CALCULATE")
            .formParam("excelReason", "업무용 트래픽 조회")
        .when().post("/web/admin/traffic/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("000"));
    }

    @Test
    void NTC_makeTrafficExcel_realtimeDaily() {
        authed()
            .formParam("searchType", "CTN")
            .formParam("searchValue", "")
            .formParam("searchTrafficType", "DOWNLOAD")
            .formParam("searchPeriodType", "SEARCH_FOR_DAY")
            .formParam("searchStartDate", "20260401")
            .formParam("searchEndDate", "20260415")
            .formParam("searchDataType", "REAL_TIME")
            .formParam("excelReason", "실시간 다운로드 트래픽")
        .when().post("/web/admin/traffic/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("000"));
    }

    @Test
    void NTC_makeTrafficExcel_uploadMonthly() {
        authed()
            .formParam("searchType", "CTN")
            .formParam("searchValue", "")
            .formParam("searchTrafficType", "UPLOAD")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchStartDate", "20260201")
            .formParam("searchEndDate", "20260228")
            .formParam("searchDataType", "CALCULATE")
            .formParam("excelReason", "업로드 트래픽 집계")
        .when().post("/web/admin/traffic/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("000"));
    }

    // ---------------------------------------------------------------- VTC

    @Test
    void VTC_excelReason_SPECIAL_CHAR() {
        // excelReason XSS 취약값 → CommonUtil.isVulnerability true → "002"
        authed()
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("searchDataType", "CALCULATE")
            .formParam("excelReason", "<script>alert('xss')</script>")
        .when().post("/web/admin/traffic/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("002"));
    }

    // ---------------------------------------------------------------- ATC

    @Test
    void ATC_makeTrafficExcel_noSession() {
        // 세션 없이 POST → "/ajax" 미포함 URI → 302 redirect (POST 302 는 follow 안 함)
        given().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("searchDataType", "CALCULATE")
            .formParam("excelReason", "x")
            .redirects().follow(false)
        .when().post("/web/admin/traffic/excel/make")
        .then().statusCode(302);
    }
}

