import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

/**
 * Black-Box API Integration Test
 *
 * @target-controller ClientController (src/main/java/com/ahope/ds/web/superadmin/client/controller/ClientController.java)
 * @target-api PUT /web/super/admin/clients/{clientSeq}/cancel
 *
 * 인증: SuperAdminLoginInterceptor (세션, AUTHZ='07'=SYSTEM).
 * 서비스: ClientService.modifyClientCancel.
 *   - LPS 등록(01/03) 가입자 존재 → err="001", errMsg="UNABLE_TO_CLIENT_CANCEL_...".
 *   - CANCEL_STATUS='01'(가입) → '02'(해지요청) 으로 변경, err="000".
 *   - '06'(해지) 는 즉시파기(복잡 경로) — 본 테스트 범위 외. 그 외 상태는 no-op.
 * @History(PERSONAL_INFO_DELETE) 는 deleteCount 가 있는 즉시파기 경로에서만 이력 기록 → 01→02 경로는 이력 없음.
 * 응답: HTTP 200, JSON { err, ... }. 외부 HTTP 연동 없음 → WireMock 불필요.
 *
 * 병렬 격리: 인증 픽스처 클래스 단위, 고객사는 메서드별 고유 CLIENT_SEQ.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
@Execution(ExecutionMode.CONCURRENT)
class SuperAdminClientsCancelBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:13306/smart_plant");
    private static final String DB_USER = System.getProperty("test.db.user", "smartplant");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "smartplant1234");

    private static final String ADMIN_ID = "sysclient";
    private static final String ADMIN_PW = "testpw";
    private static String sessionId;

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private static long uniqueSeq(TestInfo info) {
        return 900_000_000L + Math.floorMod(info.getTestMethod().get().getName().hashCode(), 90_000_000L);
    }

    private static Map<String, String> params(long seq, String status) {
        Map<String, String> m = new HashMap<>();
        m.put("SEQ", String.valueOf(seq));
        m.put("STATUS", status);
        return m;
    }

    @BeforeAll
    void beforeAll() throws Exception {
        RestAssured.baseURI = BASE_URL;
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/super-admin-clients-cancel-teardown.sql", getClass());
            TestUtil.executeSql(conn, "sql/super-admin-clients-cancel-setup.sql", getClass());
            sessionId = TestUtil.adminLogin(BASE_URL, ADMIN_ID, ADMIN_PW, conn);
        }
    }

    @AfterAll
    void afterAll() throws Exception {
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/super-admin-clients-cancel-teardown.sql", getClass());
        }
    }

    private String cancelStatus(long seq) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(
                "SELECT CANCEL_STATUS FROM CLIENT WHERE CLIENT_SEQ = ?")) {
            ps.setLong(1, seq);
            try (ResultSet rs = ps.executeQuery()) {
                Assertions.assertTrue(rs.next(), "client must exist");
                return rs.getString(1);
            }
        }
    }

    // ---------------------------------------------------------------- NTC

    @Test
    void NTC_modifyClientCancel_joinToCancelReq(TestInfo info) throws Exception {
        long seq = uniqueSeq(info);
        Map<String, String> p = params(seq, "01");
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-teardown.sql", p, getClass());
            TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-setup.sql", p, getClass());
        }
        try {
            given().baseUri(BASE_URL)
                .cookie("SESSION", sessionId)
                .header("X-Requested-With", "XMLHttpRequest")
            .when()
                .put("/web/super/admin/clients/" + seq + "/cancel")
            .then().statusCode(200)
                .body("err", equalTo("000"));
            Assertions.assertEquals("02", cancelStatus(seq), "가입(01) → 해지요청(02)");
        } finally {
            try (Connection conn = getDbConnection()) {
                TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-teardown.sql", p, getClass());
            }
        }
    }

    @Test
    void NTC_modifyClientCancel_anotherJoinClient(TestInfo info) throws Exception {
        long seq = uniqueSeq(info);
        Map<String, String> p = params(seq, "01");
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-teardown.sql", p, getClass());
            TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-setup.sql", p, getClass());
        }
        try {
            given().baseUri(BASE_URL)
                .cookie("SESSION", sessionId)
                .header("X-Requested-With", "XMLHttpRequest")
            .when()
                .put("/web/super/admin/clients/" + seq + "/cancel")
            .then().statusCode(200)
                .body("err", equalTo("000"));
            Assertions.assertEquals("02", cancelStatus(seq));
        } finally {
            try (Connection conn = getDbConnection()) {
                TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-teardown.sql", p, getClass());
            }
        }
    }

    @Test
    void NTC_modifyClientCancel_alreadyCancelReqNoop(TestInfo info) throws Exception {
        // 이미 해지요청(02) 상태 → 어느 분기에도 해당 안 됨 → no-op, err="000", 상태 유지
        long seq = uniqueSeq(info);
        Map<String, String> p = params(seq, "02");
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-teardown.sql", p, getClass());
            TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-setup.sql", p, getClass());
        }
        try {
            given().baseUri(BASE_URL)
                .cookie("SESSION", sessionId)
                .header("X-Requested-With", "XMLHttpRequest")
            .when()
                .put("/web/super/admin/clients/" + seq + "/cancel")
            .then().statusCode(200)
                .body("err", equalTo("000"));
            Assertions.assertEquals("02", cancelStatus(seq), "상태 변화 없음");
        } finally {
            try (Connection conn = getDbConnection()) {
                TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-teardown.sql", p, getClass());
            }
        }
    }

    // ---------------------------------------------------------------- ATC

    @Test
    void ATC_modifyClientCancel_lpsJoinedMemberBlocks(TestInfo info) throws Exception {
        // LPS 등록(01) 가입자 존재 → 해지 불가 → err="001"
        long seq = uniqueSeq(info);
        Map<String, String> p = params(seq, "01");
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-teardown.sql", p, getClass());
            TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-setup.sql", p, getClass());
            TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-lps-setup.sql", p, getClass());
        }
        try {
            given().baseUri(BASE_URL)
                .cookie("SESSION", sessionId)
                .header("X-Requested-With", "XMLHttpRequest")
            .when()
                .put("/web/super/admin/clients/" + seq + "/cancel")
            .then().statusCode(200)
                .body("err", equalTo("001"))
                .body("errMsg", equalTo("UNABLE_TO_CLIENT_CANCEL_BECAUSE_EXIST_JOINED_MEMBER_IN_THE_LPS"));
            Assertions.assertEquals("01", cancelStatus(seq), "해지 차단 시 상태 유지");
        } finally {
            try (Connection conn = getDbConnection()) {
                TestUtil.executeSqlTemplate(conn, "sql/super-admin-clients-cancel-data-teardown.sql", p, getClass());
            }
        }
    }

    @Test
    void ATC_modifyClientCancel_noSession(TestInfo info) {
        long seq = uniqueSeq(info);
        given().baseUri(BASE_URL)
            .redirects().follow(false)
        .when()
            .put("/web/super/admin/clients/" + seq + "/cancel")
        .then().statusCode(302);
    }
}

