package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.hasItems;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.HashMap;
import java.util.Map;

import io.restassured.RestAssured;
import io.restassured.specification.RequestSpecification;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

/**
 * Black-Box API Integration Test
 *
 * @target-controller ClientAPIController (src/main/java/com/ahope/ds/client/controller/ClientAPIController.java)
 * @target-api GET /client/sync
 *
 * 인증: ClientLoginInterceptor (무세션). Authorization: Bearer &lt;CMK-4 암호문&gt; 필요.
 *   토큰 payload(JSON) = { tokenType:"ACCESS", expiredAt:"yyyyMMddHHmmss"(미래), memberSeq, clientSeq }.
 *   추가 필수 헤더: X-Manufacturer, X-Model, X-OS-Version, X-App-Version.
 * 서비스: ClientAPIService.sync → 약관/공지/고객사동기화/연동앱/허용ECGI(CMK-1 복호화)/솔루션 조회.
 * 응답: HTTP 200, ClientResultMap { code:"200", message:"OK", data:{...} }.
 *   에러코드: "816"=토큰 없음, "812"=유효하지 않은 토큰, "011"=필수 헤더 누락.
 * 외부 HTTP 연동 없음 (토큰/ECGI 복호화는 KMS=LocalStack) → WireMock 불필요.
 *
 * 병렬 격리: 무세션 + 토큰이므로 모든 데이터를 메서드별 고유 clientSeq 로 완전 격리한다.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
@Execution(ExecutionMode.CONCURRENT)
class ClientSyncBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:13306/smart_plant");
    private static final String DB_USER = System.getProperty("test.db.user", "smartplant");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "smartplant1234");

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private static long uniqueSeq(TestInfo info) {
        return 700_000_000L + Math.floorMod(info.getTestMethod().get().getName().hashCode(), 90_000_000L);
    }

    @BeforeAll
    void beforeAll() {
        RestAssured.baseURI = BASE_URL;
    }

    /** CMK-4 로 암호화된 유효 ACCESS 토큰 생성. */
    private static String accessToken(long memberSeq, long clientSeq) {
        String json = "{\"tokenType\":\"ACCESS\",\"expiredAt\":\"20991231235959\",\"memberSeq\":"
                + memberSeq + ",\"clientSeq\":" + clientSeq + "}";
        return TestUtil.kmsEncryptToken(json);
    }

    private RequestSpecification clientHeaders(String bearer) {
        RequestSpecification spec = given().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01");
        if (bearer != null) spec = spec.header("Authorization", "Bearer " + bearer);
        return spec;
    }

    private Map<String, String> data(long seq, String bkgd, int appVer, String appName, String pkg) {
        Map<String, String> m = new HashMap<>();
        m.put("SEQ", String.valueOf(seq));
        m.put("E1", String.valueOf(seq * 10 + 1));
        m.put("E2", String.valueOf(seq * 10 + 2));
        m.put("BKGD", bkgd);
        m.put("APPVER", String.valueOf(appVer));
        m.put("APPNAME", appName);
        m.put("PKG", pkg);
        return m;
    }

    // ---------------------------------------------------------------- NTC

    private void runSyncCase(TestInfo info, String bkgd, int appVer, String appName, String pkg,
            String ecgi1, String ecgi2) throws Exception {
        long seq = uniqueSeq(info);
        Map<String, String> p = data(seq, bkgd, appVer, appName, pkg);
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSqlTemplate(conn, "sql/client-sync-data-teardown.sql", p, getClass());
            TestUtil.executeSqlTemplate(conn, "sql/client-sync-data-setup.sql", p, getClass());
            TestUtil.encryptEcgi(conn, seq * 10 + 1, ecgi1);
            TestUtil.encryptEcgi(conn, seq * 10 + 2, ecgi2);
        }
        try {
            clientHeaders(accessToken(seq, seq))
            .when()
                .get("/client/sync")
            .then().statusCode(200)
                .body("code", equalTo("200"))
                .body("message", equalTo("OK"))
                .body("data.mainBackgroundImageUrl", equalTo(bkgd))
                .body("data.interlockingAppVersion", equalTo(appVer))
                .body("data.allowedEcgiList.size()", equalTo(2))
                .body("data.allowedEcgiList", hasItems(ecgi1, ecgi2))
                .body("data.interlockingAppList.size()", equalTo(1))
                .body("data.interlockingAppList[0].appName", equalTo(appName))
                .body("data.interlockingAppList[0].packageName", equalTo(pkg));
        } finally {
            try (Connection conn = getDbConnection()) {
                TestUtil.executeSqlTemplate(conn, "sql/client-sync-data-teardown.sql", p, getClass());
            }
        }
    }

    @Test
    void NTC_sync_basic(TestInfo info) throws Exception {
        runSyncCase(info, "https://img.example.com/bg1.png", 7, "InterApp1", "com.ahope.app1",
                "1111100001", "1111100002");
    }

    @Test
    void NTC_sync_differentClient(TestInfo info) throws Exception {
        runSyncCase(info, "https://img.example.com/bg2.png", 12, "InterApp2", "com.ahope.app2",
                "2222200001", "2222200002");
    }

    @Test
    void NTC_sync_thirdClient(TestInfo info) throws Exception {
        runSyncCase(info, "https://img.example.com/bg3.png", 3, "InterApp3", "com.ahope.app3",
                "3333300001", "3333300002");
    }

    // ---------------------------------------------------------------- ATC / VTC

    @Test
    void ATC_sync_missingToken() {
        // Authorization 헤더 없음 → ClientLoginInterceptor: MISSING_TOKEN_VALUE → code "816"
        clientHeaders(null)
        .when().get("/client/sync")
        .then().statusCode(200)
            .body("code", equalTo("816"));
    }

    @Test
    void ATC_sync_invalidToken() {
        // 복호화 불가능한 토큰 → INVALID_TOKEN → code "812"
        clientHeaders("this-is-not-a-valid-cmk4-ciphertext")
        .when().get("/client/sync")
        .then().statusCode(200)
            .body("code", equalTo("812"));
    }

    @Test
    void VTC_sync_missingManufacturerHeader(TestInfo info) throws Exception {
        // 유효 토큰이지만 X-Manufacturer 헤더 누락 → MissingRequestHeaderException → code "011"
        long seq = uniqueSeq(info);
        given().baseUri(BASE_URL)
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
            .header("Authorization", "Bearer " + accessToken(seq, seq))
        .when().get("/client/sync")
        .then().statusCode(200)
            .body("code", equalTo("011"));
    }
}

